using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PenumbraGlareCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Moonie/PenumbraGlareCustomDescription", order = 0)]
public class PenumbraGlareCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		DrawGainHexDieAction drawGainHexDieAction = battleAction as DrawGainHexDieAction;
		string actionDescription = drawGainHexDieAction.DrawAction.GetActionDescription(GetAmountWithoutEquation(amountModified));
		string actionDescription2 = drawGainHexDieAction.HexAction.GetActionDescription(drawGainHexDieAction.HexAmount);
		return actionDescription + "\n" + actionDescription2;
	}
}
